import{_ as r,o as a,c as e,ag as d}from"./chunks/framework.BjY7aUvS.js";const b=JSON.parse('{"title":"宝宝疫苗指南 · 程序表、接种记录与两个极端","description":"宝宝疫苗指南：国家免疫规划程序速览、接种证与记录查询、自费疫苗的知情选择、两个极端误区。","frontmatter":{"title":"宝宝疫苗指南 · 程序表、接种记录与两个极端","issuer":"依据国家免疫规划程序及中国疾控中心公开信息整理","source_tier":"一级来源","version":"2021年版免疫程序","published":2021,"source_url":"https://www.chinacdc.cn/","status":"现行","tags":["家庭办事","疫苗","宝宝","免疫规划","接种证"],"type":"家庭办事","reviewed":false,"description":"宝宝疫苗指南：国家免疫规划程序速览、接种证与记录查询、自费疫苗的知情选择、两个极端误区。"},"headers":[],"relativePath":"family/vaccine.md","filePath":"family/vaccine.md"}'),o={name:"family/vaccine.md"};function n(l,t,s,i,h,c){return a(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="宝宝疫苗指南-·-程序表、接种记录与两个极端" tabindex="-1">宝宝疫苗指南 · 程序表、接种记录与两个极端 <a class="header-anchor" href="#宝宝疫苗指南-·-程序表、接种记录与两个极端" aria-label="Permalink to &quot;宝宝疫苗指南 · 程序表、接种记录与两个极端&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据《国家免疫规划疫苗儿童免疫程序及说明（2021 年版）》等整理；<strong>月龄与剂次请以接种证和当地疾控为准</strong>（各地安排略有差异）。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页内容<strong>整理自国家免疫规划程序</strong>（一级来源）。接种方案请遵接种医生，本站不构成医疗建议。</p></div><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><ul><li><strong>免疫规划疫苗（免费）</strong>：国家&quot;规定动作&quot;，<strong>必须按时打</strong>——入托入学要查验接种证。</li><li><strong>非免疫规划疫苗（自费）</strong>：知情、自愿原则——是家庭的选择题，不是智商税，也不是必须全打。</li><li>接种凭证：<strong>预防接种证</strong>（纸质小绿本）——终身保存，比出生证使用频率还高。</li></ul><h2 id="免疫规划程序速览-0-6-岁-简化版-待核验" tabindex="-1">免疫规划程序速览（0～6 岁，简化版，待核验） <a class="header-anchor" href="#免疫规划程序速览-0-6-岁-简化版-待核验" aria-label="Permalink to &quot;免疫规划程序速览（0～6 岁，简化版，待核验）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>月龄</th><th>常见剂次（简记）</th></tr></thead><tbody><tr><td>出生 24h 内</td><td>乙肝第 1 剂、卡介苗</td></tr><tr><td>1 / 6 月龄</td><td>乙肝第 2 / 3 剂</td></tr><tr><td>2～5 月龄</td><td>脊灰、百白破基础免疫</td></tr><tr><td>6～9 月龄</td><td>流脑 A 群、乙脑（按当地安排）</td></tr><tr><td>8 月龄</td><td>麻腮风第 1 剂</td></tr><tr><td>18 月龄</td><td>百白破加强、麻腮风第 2 剂、甲肝</td></tr><tr><td>2 / 3 / 4 / 6 周岁</td><td>乙脑加强、流脑 A+C、脊灰第 4 剂、白破加强</td></tr></tbody></table><p>完整程序与补种规则：见《国家免疫规划疫苗儿童免疫程序及说明（2021 年版）》（<a href="https://www.chinacdc.cn/" target="_blank" rel="noreferrer">中国疾控中心</a>发布，待核验）。</p><h2 id="行动清单" tabindex="-1">行动清单 <a class="header-anchor" href="#行动清单" aria-label="Permalink to &quot;行动清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>每次接种<strong>带齐接种证</strong>并当场核对记录</td><td>接种单位</td></tr><tr><td>接种记录查询：<strong>无全国统一入口</strong>——用当地疾控/健康云 App（如&quot;首都疫苗服务&quot;等），或以接种证为准</td><td>各地（待核验）</td></tr><tr><td>漏种不慌：按程序说明<strong>补种</strong>，接种医生会给补种方案</td><td>2021 年版程序</td></tr><tr><td>想核验疫苗&quot;出身&quot;：中检院有<strong>批签发</strong>信息查询（<a href="https://www.nifdc.org.cn/" target="_blank" rel="noreferrer">nifdc.org.cn</a>，站点证书异常，入口以药监局官网为准）</td><td>中检院</td></tr><tr><td>入托入学前：提前查漏补种（学校要查验接种证）</td><td>《疫苗管理法》要求</td></tr></tbody></table><h2 id="两个极端都要躲" tabindex="-1">两个极端都要躲 <a class="header-anchor" href="#两个极端都要躲" aria-label="Permalink to &quot;两个极端都要躲&quot;">​</a></h2><table tabindex="0"><thead><tr><th>极端</th><th>事实</th></tr></thead><tbody><tr><td>&quot;自费疫苗都是坑钱&quot;</td><td>非免疫规划疫苗是免疫规划的<strong>重要补充</strong>（如流感、水痘、肺炎等），官方态度是<strong>知情自愿</strong>——按家庭风险选择，而不是一票否决</td></tr><tr><td>&quot;全都打最贵的才安心&quot;</td><td>疫苗不是越贵越好；同类联苗与单苗各有取舍，问接种医生，别被营销绑架</td></tr><tr><td>【本站提示】看到&quot;疫苗致病&quot;类爆款文章：先去<a href="https://www.piyao.org.cn/" target="_blank" rel="noreferrer">辟谣平台</a>查证</td><td>—</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li>出生那条线：<a href="/SageRelay/family/baby-checklist.html">宝宝出生 30 天办事清单</a></li><li>谣言查证：<a href="/SageRelay/query/daily-tools.html">延伸工具站 · 辟谣平台</a></li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>依据</td><td>《国家免疫规划疫苗儿童免疫程序及说明（2021 年版）》《疫苗管理法》（待核验）</td></tr><tr><td>入口</td><td><a href="https://www.chinacdc.cn/" target="_blank" rel="noreferrer">中国疾控中心</a> · 中检院批签发（证书异常标注）· 12320 卫生热线</td></tr></tbody></table>',16)])])}const g=r(o,[["render",n]]);export{b as __pageData,g as default};
